python3 -c "
import json
with open('/app/resources/treasury_bulletin_2014_06.json') as f:
    data = json.load(f)
# Search for 2025 in all strings
found = set()
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if '2025' in str(k) or '2025' in str(v):
                found.add(f'{path}.{k}: {str(v)[:200]}')
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            if '2025' in str(item):
                found.add(f'{path}[{i}]: {str(item)[:200]}')
            search(item, f'{path}[{i}]')
search(data)
for f in sorted(found):
    print(f[:200])
"
